content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --secondary-color: #f3f4f6;
  --secondary-hover: #e5e7eb;
  --text-main: #1f2937;
  --text-sub: #6b7280;
  --bg-color: #f9fafb;
  --card-bg: #ffffff;
  --border-color: #e5e7eb;
  --shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  text-align: center;
  margin-bottom: 4px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-sub);
}

.instruction {
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-sub);
  background-color: #eef2ff;
  padding: 8px 12px;
  border-radius: 8px;
  margin-bottom: 4px;
}

.card-container {
  perspective: 1000px;
  width: 100%;
  height: 280px;
  cursor: pointer;
}

.card {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.4, 0.2, 0.2, 1);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
}

.card.is-flipped {
  transform: rotateY(180deg);
}

.card-inner {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 24px;
  border-radius: var(--radius);
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  text-align: center;
}

.card-front {
  z-index: 2;
}

.card-back {
  transform: rotateY(180deg);
  background-color: #faf5ff;
  border-color: #e9d5ff;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  align-items: center;
}

.btn {
  padding: 10px 18px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--secondary-color);
  color: var(--text-main);
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
}

.progress {
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: center;
}

.stats {
  font-size: 0.875rem;
  color: var(--text-sub);
  font-weight: 500;
}

export interface WordCard {
  id: string;
  english: string;
  pronunciation: string;
  meaning: string;
  example: string;
}

import { useState } from 'react';
import './index.css';
import { WordCard } from './types';

const initialWords: WordCard[] = [
  {
    id: '1',
    english: 'Apple',
    pronunciation: '/ˈæp.əl/',
    meaning: 'りんご',
    example: 'I eat an apple every morning.'
  },
  {
    id: '2',
    english: 'Book',
    pronunciation: '/bʊk/',
    meaning: '本',
    example: 'She is reading an interesting book.'
  },
  {
    id: '3',
    english: 'Computer',
    pronunciation: '/kəmˈpjuː.tər/',
    meaning: 'コンピューター',
    example: 'He works on his computer all day.'
  },
  {
    id: '4',
    english: 'Dog',
    pronunciation: '/dɒɡ/',
    meaning: '犬',
    example: 'The dog is running in the park.'
  },
  {
    id: '5',
    english: 'Elephant',
    pronunciation: '/ˈel.ɪ.fənt/',
    meaning: '象',
    example: 'An elephant has a long trunk.'
  },
  {
    id: '6',
    english: 'Friend',
    pronunciation: '/frend/',
    meaning: '友達',
    example: 'She is my best friend.'
  },
  {
    id: '7',
    english: 'Guitar',
    pronunciation: '/ɡɪˈtɑːr/',
    meaning: 'ギター',
    example: 'He likes to play the guitar.'
  },
  {
    id: '8',
    english: 'House',
    pronunciation: '/haʊs/',
    meaning: '家',
    example: 'They live in a big house.'
  },
  {
    id: '9',
    english: 'Island',
    pronunciation: '/ˈaɪ.lənd/',
    meaning: '島',
    example: 'We visited a tropical island.'
  },
  {
    id: '10',
    english: 'Journey',
    pronunciation: '/ˈdʒɜː.ni/',
    meaning: '旅、旅行',
    example: 'Life is a long journey.'
  }
];

export default function App() {
  const [words, setWords] = useState<WordCard[]>(initialWords);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [isFlipped, setIsFlipped] = useState<boolean>(false);
  const [correctCount, setCorrectCount] = useState<number>(0);
  const [incorrectCount, setIncorrectCount] = useState<number>(0);
  const [isFinished, setIsFinished] = useState<boolean>(false);

  const currentWord = words[currentIndex];

  const handleCardClick = () => {
    setIsFlipped(!isFlipped);
  };

  const handleNext = () => {
    setIsFlipped(false);
    if (currentIndex < words.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setIsFinished(true);
    }
  };

  const handlePrev = () => {
    setIsFlipped(false);
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const handleShuffle = () => {
    const shuffled = [...words].sort(() => Math.random() - 0.5);
    setWords(shuffled);
    setCurrentIndex(0);
    setIsFlipped(false);
    setCorrectCount(0);
    setIncorrectCount(0);
    setIsFinished(false);
  };

  const handleJudgment = (isCorrect: boolean) => {
    if (isCorrect) {
      setCorrectCount(correctCount + 1);
    } else {
      setIncorrectCount(incorrectCount + 1);
    }
    handleNext();
  };

  const handleReset = () => {
    setCurrentIndex(0);
    setIsFlipped(false);
    setCorrectCount(0);
    setIncorrectCount(0);
    setIsFinished(false);
  };

  return (
    <div className="app-container">
      <div className="header">
        <h1 className="title">英単語暗記カード</h1>
        <p className="subtitle">カードをタップして意味を確認しよう</p>
      </div>

      <div className="instruction">
        ヒント: カードをクリックすると裏返ります
      </div>

      {!isFinished ? (
        <>
          <div className="card-container" onClick={handleCardClick}>
            <div className={`card ${isFlipped ? 'is-flipped' : ''}`}>
              <div className="card-inner card-front">
                <h2 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '8px' }}>
                  {currentWord.english}
                </h2>
                <p style={{ color: 'var(--text-sub)', fontSize: '1rem' }}>
                  {currentWord.pronunciation}
                </p>
              </div>
              <div className="card-inner card-back">
                <h3 style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--primary-color)', marginBottom: '8px' }}>
                  {currentWord.meaning}
                </h3>
                <p style={{ fontStyle: 'italic', color: 'var(--text-main)', fontSize: '0.95rem' }}>
                  "{currentWord.example}"
                </p>
              </div>
            </div>
          </div>

          <div className="controls">
            <button className="btn btn-secondary" onClick={handlePrev} disabled={currentIndex === 0}>
              前へ
            </button>
            <button className="btn btn-secondary" onClick={handleShuffle}>
              シャッフル
            </button>
            <button className="btn btn-primary" onClick={handleNext}>
              次へ
            </button>
          </div>

          {isFlipped && (
            <div className="controls" style={{ marginTop: '4px' }}>
              <button 
                className="btn btn-secondary" 
                style={{ backgroundColor: '#fee2e2', color: '#991b1b', flex: 1 }}
                onClick={(e) => { e.stopPropagation(); handleJudgment(false); }}
              >
                ✕ わからない
              </button>
              <button 
                className="btn btn-primary" 
                style={{ backgroundColor: '#dcfce7', color: '#166534', flex: 1 }}
                onClick={(e) => { e.stopPropagation(); handleJudgment(true); }}
              >
                〇 覚えた
              </button>
            </div>
          )}

          <div className="progress">
            <div className="stats">
              カード: {currentIndex + 1} / {words.length}
            </div>
            <div className="stats" style={{ display: 'flex', justifyContent: 'center', gap: '16px' }}>
              <span style={{ color: '#166534' }}>〇 覚えた: {correctCount}</span>
              <span style={{ color: '#991b1b' }}>✕ わからない: {incorrectCount}</span>
            </div>
          </div>
        </>
      ) : (
        <div className="card-inner" style={{ backgroundColor: 'white', border: '1px solid var(--border-color)', height: '280px' }}>
          <h2 style={{ fontSize: '1.5rem', fontWeight: 'bold', marginBottom: '12px', color: 'var(--primary-color)' }}>
            お疲れ様でした！
          </h2>
          <p style={{ marginBottom: '8px', fontSize: '1rem' }}>すべてのカードを確認しました。</p>
          <div style={{ marginBottom: '20px', fontSize: '1rem' }}>
            <p style={{ color: '#166534' }}>覚えた数: {correctCount}</p>
            <p style={{ color: '#991b1b' }}>わからない数: {incorrectCount}</p>
          </div>
          <button className="btn btn-primary" onClick={handleReset}>
            最初からもう一度やる
          </button>
        </div>
      )}
    </div>
  );
}
